<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)post('id');$image=$pdo->prepare('SELECT image_path FROM products WHERE id=? AND seller_id=?');$image->execute([$id,$sid]);$path=$image->fetchColumn();$pdo->prepare('DELETE FROM products WHERE id=? AND seller_id=?')->execute([$id,$sid]);delete_product_upload($path?:null);flash('success','Listing and its uploaded photo were deleted.');redirect('seller/products.php');}$s=$pdo->prepare('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.seller_id=? ORDER BY p.created_at DESC');$s->execute([$sid]);$products=$s->fetchAll();$pageTitle='My listings';require '../includes/header.php';?><div class="page-title inline"><div><p class="eyebrow">SELLER CATALOGUE</p><h1>My fish listings</h1></div><a class="button" href="add-product.php">Add listing</a></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price/kg</th><th>Stock</th><th>Availability</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['category'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><?=$p['stock']?> kg</td><td><span class="badge <?=$p['is_available']?'delivered':'cancelled'?>"><?=$p['is_available']?'Available':'Hidden'?></span></td><td><a href="edit-product.php?id=<?=$p['id']?>">Edit</a> <form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="text-button" data-confirm="Delete this listing and its uploaded photo?">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$products):?><div class="empty"><h2>No listings yet.</h2><a href="add-product.php">Add your first catch</a></div><?php endif;require '../includes/footer.php'; ?>
